window.MG_LAZY_DATA["data/lazy/owner-courses/b288-e5dc77ce13ee1eed.json"]={sha256:"e5dc77ce13ee1eed7a46ddacda5e7a6dc1af7fa1b2d5bf72be427836392d74af",value:{"id":"b288","title":"疏浚泥沙有益利用","titleEn":"Beneficial reuse of dredged sediment","category":"water","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"用材料分流地形高程和生態追蹤判斷疏浚土的有益利用。課程從邊界辨識與資料整理走到水理量化、構造介面及驗證紀錄；每一步把計算結果連回可量測的證據。十個不同單元分別處理關鍵機制，不以名義尺寸或單一通過率代替整體工程判斷，並明列合成算例與現地資料的差別。","summaryEn":"Evaluate dredged-sediment reuse through material routing, elevation and ecological follow-up. The course moves from boundary identification and evidence to hydraulic quantification, structural interfaces and verification records. Ten distinct units connect each calculated quantity to measurable evidence. Nominal geometry or a single pass rate does not establish whole-system performance, and synthetic teaching examples remain separate from field observations.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、開挖、注漿或受限空間作業許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, excavation, grouting or confined-space permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"water-coasts","subcategoryTitle":"海岸、港灣與水資源韌性","subcategoryTitleEn":"Coasts, ports and water-resource resilience","learningTrack":"water","learningSubdiscipline":"water-coasts","learningTags":["water","water-coasts","water"],"architectureFamily":"water-coast","architectureNodes":[["材料分流與去向","Material routing and destinations"],["壓密後高程餘量","Post-consolidation elevation reserve"],["篩分回收與產率","Screening recovery and yield"],["覆蓋厚度與侵蝕餘量","Cover thickness and erosion reserve"],["對照監測與歸因","Control monitoring and attribution"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,1]],"diagram":{"type":"water-coast","labels":["材料分流與去向","壓密後高程餘量","篩分回收與產率","覆蓋厚度與侵蝕餘量","對照監測與歸因"],"labelsEn":["Material routing and destinations","Post-consolidation elevation reserve","Screening recovery and yield","Cover thickness and erosion reserve","Control monitoring and attribution"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"以下為原創合成算例，不是地標工程的實測或推薦操作值。教學假設，非操作設定或設計允收值。假設乾固體10000t中砂6500t、細料3000t、雜物500t，質量守恆10000t；若僅砂獲適用驗證，確認再利用率65%。假設其他類別保持不變，已驗證砂量6500增10%至7150t，總料由10000增至10650t，確認利用率為67.14%，並非原65%加10百分點。重新計算前先列固定條件、單位、適用尺度及可能失效的邊界。把模型敏感度與測量誤差分開，不能將單一參數變化直接當成工程風險或壽命比例。比較兩次結果後，記錄還需要哪些獨立證據，並由負責專業人員判斷適用性。","textEn":"This original synthetic example is neither a landmark measurement nor a recommended operating value. Teaching assumptions, not operating settings or design acceptance limits. Assume dry solids10000t comprise sand6500t,fines3000t and debris500t. Balance closes; if only sand is verified suitable, confirmed reuse is65%. If verified sand increases10% from6500 to7150t while other classes remain fixed, total feed becomes10650t and confirmed reuse is67.14%, not65% plus ten percentage points. Before recalculating, list fixed conditions, units, applicable scale and boundaries that could fail. Separate model sensitivity from measurement uncertainty: a parameter change does not directly give a proportional change in engineering risk or service life. Compare the results, record independent evidence still needed, and have the responsible specialist determine applicability.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":15,"enrichmentVersion":15,"stages":[{"id":"b288-v15-s1","title":"水文條件、邊界與工程系統","titleEn":"Hydrology, boundaries and engineering system","description":"本階段聚焦「材料分流與去向」與「薄層放置與高程」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Material routing and destinations\" and \"Thin-layer placement and elevation\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b288-v15-01","title":"材料分流與去向：機制與系統路徑","titleEn":"Material routing and destinations: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":[],"objective":"說明「材料分流與去向」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Material routing and destinations” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"有益利用先確認可用材料類別與接收目的，不能將全部挖出量直接算成成功利用。篩分、脫水和不合用材料各有去向，所有分類需用一致乾質量基準並避免重複計數；接收場適合性還有污染、鹽分與地工條件，帳面分流不能取代證據。 假設乾固體10000t中砂6500t、細料3000t、雜物500t，質量守恆10000t；若僅砂獲適用驗證，確認再利用率65%。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「材料分流與去向」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Beneficial reuse starts with material classification and receiving purpose rather than counting all excavation as successful use. Screening, dewatering and unsuitable fractions have distinct destinations that require one dry-mass basis and no duplicate counting. Suitability additionally depends on contaminants, salinity and geotechnical behavior, so an accounting split cannot substitute for evidence of fitness at the receiving site. Assume dry solids10000t comprise sand6500t,fines3000t and debris500t. Balance closes; if only sand is verified suitable, confirmed reuse is65%. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Material routing and destinations” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「疏浚材料只要有預定去向就全部算成已驗證成功再利用。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Every dredged batch with a planned destination already counts as verified successful reuse.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「材料分流與去向」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Material routing and destinations”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-01-k1","title":"材料分流與去向","titleEn":"Material routing and destinations","text":"有益利用先確認可用材料類別與接收目的，不能將全部挖出量直接算成成功利用。篩分、脫水和不合用材料各有去向，所有分類需用一致乾質量基準並避免重複計數；接收場適合性還有污染、鹽分與地工條件，帳面分流不能取代證據。","textEn":"Beneficial reuse starts with material classification and receiving purpose rather than counting all excavation as successful use. Screening, dewatering and unsuitable fractions have distinct destinations that require one dry-mass basis and no duplicate counting.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：疏浚材料只要有預定去向就全部算成已驗證成功再利用。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Every dredged batch with a planned destination already counts as verified successful reuse. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「材料分流與去向」，下列哪一項敘述正確？","questionEn":"Which statement about \"Material routing and destinations\" is correct?","options":["疏浚材料只要有預定去向就全部算成已驗證成功再利用。","有益利用先確認可用材料類別與接收目的，不能將全部挖出量直接算成成功利用。","平均放置厚度達標就能證明每個位置的淹水條件都合適。"],"optionsEn":["Every dredged batch with a planned destination already counts as verified successful reuse.","Beneficial reuse starts with material classification and receiving purpose rather than counting all excavation as successful use.","A satisfactory mean placement thickness proves suitable inundation at every location."],"answer":1,"explanation":"有益利用先確認可用材料類別與接收目的，不能將全部挖出量直接算成成功利用。 其餘選項是常見誤解。","explanationEn":"Beneficial reuse starts with material classification and receiving purpose rather than counting all excavation as successful use. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b288-v15-02","title":"材料分流與去向：定量估算","titleEn":"Material routing and destinations: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-01"],"objective":"以數值模型估算「材料分流與去向」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Material routing and destinations” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設乾固體10000t中砂6500t、細料3000t、雜物500t，質量守恆10000t；若僅砂獲適用驗證，確認再利用率65%。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume dry solids10000t comprise sand6500t,fines3000t and debris500t. Balance closes; if only sand is verified suitable, confirmed reuse is65%. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。","observationEn":"How to cross-check: Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設乾固體10000t中砂6500t、細料3000t、雜物500t，質量守恆10000t；若僅砂獲適用驗證，確認再利用率65%。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume dry solids10000t comprise sand6500t,fines3000t and debris500t. Balance closes; if only sand is verified suitable, confirmed reuse is65%.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「材料分流與去向」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Material routing and destinations\", which statement holds?","options":["潮位超過地面的時間比例直接等於植被的存活機率。","混合後平均濃度降低代表同百分比的污染物已被消除。","教學假設，非操作設定或設計允收值。"],"optionsEn":["The fraction of time tide exceeds ground directly equals plant survival probability.","A lower average concentration after mixing means the same fraction of contaminant was destroyed.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b288-v15-03","title":"材料分流與去向：試驗與驗證","titleEn":"Material routing and destinations: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「材料分流與去向」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Material routing and destinations” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。將待判定材料獨立保留，不以計畫去向當成已完成利用，並查證接收端實際數量和用途。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis. Keep unresolved material separate, distinguish planned destinations from completed reuse, and verify actual received quantity and purpose rather than relying only on dispatch records. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。將待判定材料獨立保留，不以計畫去向當成已完成利用，並查證接收端實際數量和用途。","observationEn":"Site practice: Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis. Keep unresolved material separate, distinguish planned destinations from completed reuse, and verify actual received quantity and purpose rather than relying only on dispatch records.","failure":"注意干擾：把含水泥漿與乾砂噸數相加會造出虛假利用量，待檢材料提前算成功也會掩蓋不合用比例。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Adding wet slurry tonnes to dry sand invents reuse quantities, and counting untested material as accepted hides unsuitable fractions. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-03-k1","title":"驗證方法","titleEn":"Verification method","text":"對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。將待判定材料獨立保留，不以計畫去向當成已完成利用，並查證接收端實際數量和用途。","textEn":"Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis. Keep unresolved material separate, distinguish planned destinations from completed reuse, and verify actual received quantity and purpose rather than relying only on dispatch records.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-03-k2","title":"現場實務","titleEn":"Site practice","text":"對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。將待判定材料獨立保留，不以計畫去向當成已完成利用，並查證接收端實際數量和用途。","textEn":"Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis. Keep unresolved material separate, distinguish planned destinations from completed reuse, and verify actual received quantity and purpose rather than relying only on dispatch records.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「材料分流與去向」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Material routing and destinations\"?","options":["對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","表面變乾就代表全部填料已完全排水並取得最終強度。"],"optionsEn":["Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","A dry surface proves that the entire fill has drained and reached final strength."],"answer":0,"explanation":"對每一批建立來源、檢測、處理與接收紀錄，核對三類材料是否同用乾質量。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Trace each batch through source, testing, treatment and receipt, checking a common dry-mass basis. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b288-v15-04","title":"材料分流與去向：失效診斷","titleEn":"Material routing and destinations: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-03"],"objective":"從症狀倒推「材料分流與去向」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Material routing and destinations” and propose discriminating checks, corrective actions and prevention.","instruction":"把含水泥漿與乾砂噸數相加會造出虛假利用量，待檢材料提前算成功也會掩蓋不合用比例。不同接收場需要的性質不同，不能以一處通過代表全用途適用。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Adding wet slurry tonnes to dry sand invents reuse quantities, and counting untested material as accepted hides unsuitable fractions. Different receiving sites need different properties; acceptance for one purpose does not qualify every other use. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設乾固體10000t中砂6500t、細料3000t、雜物500t，質量守恆10000t；若僅砂獲適用驗證，確認再利用率65%。","observationEn":"Link to the mechanism: Balance closes; if only sand is verified suitable, confirmed reuse is65%.","failure":"誤判風險：若相信「疏浚材料只要有預定去向就全部算成已驗證成功再利用。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Every dredged batch with a planned destination already counts as verified successful reuse.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-04-k1","title":"失效模式","titleEn":"Failure mode","text":"把含水泥漿與乾砂噸數相加會造出虛假利用量，待檢材料提前算成功也會掩蓋不合用比例。不同接收場需要的性質不同，不能以一處通過代表全用途適用。","textEn":"Adding wet slurry tonnes to dry sand invents reuse quantities, and counting untested material as accepted hides unsuitable fractions. Different receiving sites need different properties; acceptance for one purpose does not qualify every other use.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「材料分流與去向」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Material routing and destinations\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","把含水泥漿與乾砂噸數相加會造出虛假利用量，待檢材料提前算成功也會掩蓋不合用比例。","平均放置厚度達標就能證明每個位置的淹水條件都合適。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Adding wet slurry tonnes to dry sand invents reuse quantities, and counting untested material as accepted hides unsuitable fractions.","A satisfactory mean placement thickness proves suitable inundation at every location."],"answer":1,"explanation":"把含水泥漿與乾砂噸數相加會造出虛假利用量，待檢材料提前算成功也會掩蓋不合用比例。 需以量測區分可能原因。","explanationEn":"Adding wet slurry tonnes to dry sand invents reuse quantities, and counting untested material as accepted hides unsuitable fractions. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b288-v15-05","title":"薄層放置與高程：機制與系統路徑","titleEn":"Thin-layer placement and elevation: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-04"],"objective":"說明「薄層放置與高程」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Thin-layer placement and elevation” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"濕地放置厚度決定表面相對潮位位置，但卸入泥漿體積尚含會排出的水。完成厚度需明確指排水後或長期壓密後的狀態，地面高程和植被耐受也有空間差異；一個平均厚度不能保證所有區域得到相同淹水時間或恢復條件。 假設排水後保留體積12000m³、面積60000m²且均勻，平均厚度t=V/A=0.20m；不含後續壓密沉陷。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「薄層放置與高程」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Placement thickness sets surface position relative to tides, but delivered slurry includes water that later drains. Completed thickness must identify whether it is after drainage or longer-term consolidation. Terrain and vegetation tolerance vary spatially, so a mean layer cannot establish equal inundation or recovery conditions throughout the entire restored area without additional elevation and ecological observations. Assume retained post-drainage volume12000m³ over60000m² uniformly. Mean thickness t=V/A=0.20m, excluding subsequent consolidation settlement. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Thin-layer placement and elevation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「平均放置厚度達標就能證明每個位置的淹水條件都合適。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A satisfactory mean placement thickness proves suitable inundation at every location.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「薄層放置與高程」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Thin-layer placement and elevation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-05-k1","title":"薄層放置與高程","titleEn":"Thin-layer placement and elevation","text":"濕地放置厚度決定表面相對潮位位置，但卸入泥漿體積尚含會排出的水。完成厚度需明確指排水後或長期壓密後的狀態，地面高程和植被耐受也有空間差異；一個平均厚度不能保證所有區域得到相同淹水時間或恢復條件。","textEn":"Placement thickness sets surface position relative to tides, but delivered slurry includes water that later drains. Completed thickness must identify whether it is after drainage or longer-term consolidation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：平均放置厚度達標就能證明每個位置的淹水條件都合適。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A satisfactory mean placement thickness proves suitable inundation at every location. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「薄層放置與高程」，下列哪一項敘述正確？","questionEn":"Which statement about \"Thin-layer placement and elevation\" is correct?","options":["平均放置厚度達標就能證明每個位置的淹水條件都合適。","放置材料乾固體沒有流失就代表地表高程不會再下降。","濕地放置厚度決定表面相對潮位位置，但卸入泥漿體積尚含會排出的水。"],"optionsEn":["A satisfactory mean placement thickness proves suitable inundation at every location.","If placed dry solids are retained, surface elevation cannot subsequently decrease.","Placement thickness sets surface position relative to tides, but delivered slurry includes water that later drains."],"answer":2,"explanation":"濕地放置厚度決定表面相對潮位位置，但卸入泥漿體積尚含會排出的水。 其餘選項是常見誤解。","explanationEn":"Placement thickness sets surface position relative to tides, but delivered slurry includes water that later drains. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b288-v15-06","title":"薄層放置與高程：定量估算","titleEn":"Thin-layer placement and elevation: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-05"],"objective":"以數值模型估算「薄層放置與高程」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Thin-layer placement and elevation” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設排水後保留體積12000m³、面積60000m²且均勻，平均厚度t=V/A=0.20m；不含後續壓密沉陷。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume retained post-drainage volume12000m³ over60000m² uniformly. Mean thickness t=V/A=0.20m, excluding subsequent consolidation settlement. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。","observationEn":"How to cross-check: Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設排水後保留體積12000m³、面積60000m²且均勻，平均厚度t=V/A=0.20m；不含後續壓密沉陷。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume retained post-drainage volume12000m³ over60000m² uniformly. Mean thickness t=V/A=0.20m, excluding subsequent consolidation settlement.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「薄層放置與高程」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Thin-layer placement and elevation\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","產品純度與原料回收率永遠具有相同分母而且相等。","覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","Product purity and feed recovery always share the same denominator and value.","Enough total cover volume proves adequate thickness and chemical isolation everywhere."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b288-v15-07","title":"薄層放置與高程：試驗與驗證","titleEn":"Thin-layer placement and elevation: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「薄層放置與高程」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Thin-layer placement and elevation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。按高低地分區檢查厚度與植被狀態，保留低窪及局部堆厚資料，而不讓全區平均取代空間分布。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries. Inspect thickness and vegetation by elevation zone, retaining depressions and local mounds rather than substituting a whole-site average for the distribution that controls actual inundation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。按高低地分區檢查厚度與植被狀態，保留低窪及局部堆厚資料，而不讓全區平均取代空間分布。","observationEn":"Site practice: Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries. Inspect thickness and vegetation by elevation zone, retaining depressions and local mounds rather than substituting a whole-site average for the distribution that controls actual inundation.","failure":"注意干擾：平均厚度符合計畫時局部深堆仍可能掩埋植株，低區又可能沒有足夠增高。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Local mounds can bury vegetation despite a matching mean thickness, while low areas remain insufficiently raised. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-07-k1","title":"驗證方法","titleEn":"Verification method","text":"比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。按高低地分區檢查厚度與植被狀態，保留低窪及局部堆厚資料，而不讓全區平均取代空間分布。","textEn":"Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries. Inspect thickness and vegetation by elevation zone, retaining depressions and local mounds rather than substituting a whole-site average for the distribution that controls actual inundation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-07-k2","title":"現場實務","titleEn":"Site practice","text":"比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。按高低地分區檢查厚度與植被狀態，保留低窪及局部堆厚資料，而不讓全區平均取代空間分布。","textEn":"Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries. Inspect thickness and vegetation by elevation zone, retaining depressions and local mounds rather than substituting a whole-site average for the distribution that controls actual inundation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「薄層放置與高程」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Thin-layer placement and elevation\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。","運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries.","The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit."],"answer":1,"explanation":"比較放置前後同基準高程面，標明體積對應的排水時點及施工邊界。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare pre- and post-placement surfaces on one datum, specifying drainage time and boundaries. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b288-v15-08","title":"薄層放置與高程：失效診斷","titleEn":"Thin-layer placement and elevation: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-07"],"objective":"從症狀倒推「薄層放置與高程」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Thin-layer placement and elevation” and propose discriminating checks, corrective actions and prevention.","instruction":"平均厚度符合計畫時局部深堆仍可能掩埋植株，低區又可能沒有足夠增高。泥漿排水後高程下降若未預先分辨，會讓施工方量和生態目標失去對應。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Local mounds can bury vegetation despite a matching mean thickness, while low areas remain insufficiently raised. Unrecognized lowering during slurry drainage breaks the intended link between delivered quantity and the ecological elevation objective. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設排水後保留體積12000m³、面積60000m²且均勻，平均厚度t=V/A=0.20m；不含後續壓密沉陷。","observationEn":"Link to the mechanism: Mean thickness t=V/A=0.20m, excluding subsequent consolidation settlement.","failure":"誤判風險：若相信「平均放置厚度達標就能證明每個位置的淹水條件都合適。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A satisfactory mean placement thickness proves suitable inundation at every location.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-08-k1","title":"失效模式","titleEn":"Failure mode","text":"平均厚度符合計畫時局部深堆仍可能掩埋植株，低區又可能沒有足夠增高。泥漿排水後高程下降若未預先分辨，會讓施工方量和生態目標失去對應。","textEn":"Local mounds can bury vegetation despite a matching mean thickness, while low areas remain insufficiently raised. Unrecognized lowering during slurry drainage breaks the intended link between delivered quantity and the ecological elevation objective.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「薄層放置與高程」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Thin-layer placement and elevation\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","放置材料乾固體沒有流失就代表地表高程不會再下降。","平均厚度符合計畫時局部深堆仍可能掩埋植株，低區又可能沒有足夠增高。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","If placed dry solids are retained, surface elevation cannot subsequently decrease.","Local mounds can bury vegetation despite a matching mean thickness, while low areas remain insufficiently raised."],"answer":2,"explanation":"平均厚度符合計畫時局部深堆仍可能掩埋植株，低區又可能沒有足夠增高。 需以量測區分可能原因。","explanationEn":"Local mounds can bury vegetation despite a matching mean thickness, while low areas remain insufficiently raised. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b288-v15-s2","title":"水力機制、材料與定量模型","titleEn":"Hydraulics, materials and quantitative models","description":"本階段聚焦「壓密後高程餘量」與「潮汐淹水比例」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Post-consolidation elevation reserve\" and \"Tidal inundation fraction\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b288-v15-09","title":"壓密後高程餘量：機制與系統路徑","titleEn":"Post-consolidation elevation reserve: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-08"],"objective":"說明「壓密後高程餘量」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Post-consolidation elevation reserve” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"細泥排水壓密會使放置面逐漸降低，固體體積保持時孔隙比變化可換算一維厚度縮減。真實地基也會沉陷、側向流動及有機質分解，因此這個模型只涵蓋單層材料本身；應將施工時點高程和長期目標分開，而非一次測量完成即結案。 假設初厚1m、初孔隙比e0=2、末孔隙比e1=1，末厚H1=H0(1+e1)/(1+e0)=0.667m，沉陷0.333m。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「壓密後高程餘量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Fine sediment lowers as it drains and consolidates. At fixed solid volume, void-ratio change gives a one-dimensional thickness reduction. Foundation settlement, lateral spreading and organic decomposition add other mechanisms, so this model covers only the placed layer itself. Construction elevation and long-term target must remain distinct, and one completion survey cannot close the performance assessment. Assume initial thickness1m,e0=2 and final e1=1. H1=H0(1+e1)/(1+e0)=0.667m and settlement0.333m, with fixed solid volume. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Post-consolidation elevation reserve” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「放置材料乾固體沒有流失就代表地表高程不會再下降。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"If placed dry solids are retained, surface elevation cannot subsequently decrease.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「壓密後高程餘量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Post-consolidation elevation reserve”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-09-k1","title":"壓密後高程餘量","titleEn":"Post-consolidation elevation reserve","text":"細泥排水壓密會使放置面逐漸降低，固體體積保持時孔隙比變化可換算一維厚度縮減。真實地基也會沉陷、側向流動及有機質分解，因此這個模型只涵蓋單層材料本身；應將施工時點高程和長期目標分開，而非一次測量完成即結案。","textEn":"Fine sediment lowers as it drains and consolidates. At fixed solid volume, void-ratio change gives a one-dimensional thickness reduction.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：放置材料乾固體沒有流失就代表地表高程不會再下降。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: If placed dry solids are retained, surface elevation cannot subsequently decrease. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「壓密後高程餘量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Post-consolidation elevation reserve\" is correct?","options":["細泥排水壓密會使放置面逐漸降低，固體體積保持時孔隙比變化可換算一維厚度縮減。","放置材料乾固體沒有流失就代表地表高程不會再下降。","潮位超過地面的時間比例直接等於植被的存活機率。"],"optionsEn":["Fine sediment lowers as it drains and consolidates.","If placed dry solids are retained, surface elevation cannot subsequently decrease.","The fraction of time tide exceeds ground directly equals plant survival probability."],"answer":0,"explanation":"細泥排水壓密會使放置面逐漸降低，固體體積保持時孔隙比變化可換算一維厚度縮減。 其餘選項是常見誤解。","explanationEn":"Fine sediment lowers as it drains and consolidates. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b288-v15-10","title":"壓密後高程餘量：定量估算","titleEn":"Post-consolidation elevation reserve: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-09"],"objective":"以數值模型估算「壓密後高程餘量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Post-consolidation elevation reserve” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設初厚1m、初孔隙比e0=2、末孔隙比e1=1，末厚H1=H0(1+e1)/(1+e0)=0.667m，沉陷0.333m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume initial thickness1m,e0=2 and final e1=1. H1=H0(1+e1)/(1+e0)=0.667m and settlement0.333m, with fixed solid volume. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。","observationEn":"How to cross-check: Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設初厚1m、初孔隙比e0=2、末孔隙比e1=1，末厚H1=H0(1+e1)/(1+e0)=0.667m，沉陷0.333m。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume initial thickness1m,e0=2 and final e1=1. H1=H0(1+e1)/(1+e0)=0.667m and settlement0.333m, with fixed solid volume.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「壓密後高程餘量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Post-consolidation elevation reserve\", which statement holds?","options":["混合後平均濃度降低代表同百分比的污染物已被消除。","教學假設，非操作設定或設計允收值。","表面變乾就代表全部填料已完全排水並取得最終強度。"],"optionsEn":["A lower average concentration after mixing means the same fraction of contaminant was destroyed.","Teaching assumptions, not operating settings or design acceptance limits.","A dry surface proves that the entire fill has drained and reached final strength."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b288-v15-11","title":"壓密後高程餘量：試驗與驗證","titleEn":"Post-consolidation elevation reserve: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「壓密後高程餘量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Post-consolidation elevation reserve” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。比較不同時間的高程及乾固體存量，將側向外移和有機質損失另列，不強迫所有變化符合一維式。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling. Compare elevation and dry-solid storage through time, listing lateral export and organic loss separately instead of forcing all change into one-dimensional compression. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。比較不同時間的高程及乾固體存量，將側向外移和有機質損失另列，不強迫所有變化符合一維式。","observationEn":"Site practice: Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling. Compare elevation and dry-solid storage through time, listing lateral export and organic loss separately instead of forcing all change into one-dimensional compression.","failure":"注意干擾：把原地基沉陷也算成填料壓密會誤估所需材料，未考慮側向流動又可能低估低處擴散。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Assigning foundation settlement entirely to fill consolidation misstates material demand, while omitted spreading understates movement into low areas. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-11-k1","title":"驗證方法","titleEn":"Verification method","text":"用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。比較不同時間的高程及乾固體存量，將側向外移和有機質損失另列，不強迫所有變化符合一維式。","textEn":"Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling. Compare elevation and dry-solid storage through time, listing lateral export and organic loss separately instead of forcing all change into one-dimensional compression.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-11-k2","title":"現場實務","titleEn":"Site practice","text":"用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。比較不同時間的高程及乾固體存量，將側向外移和有機質損失另列，不強迫所有變化符合一維式。","textEn":"Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling. Compare elevation and dry-solid storage through time, listing lateral export and organic loss separately instead of forcing all change into one-dimensional compression.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「壓密後高程餘量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Post-consolidation elevation reserve\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","處理區施工後植被增加就足以證明增長完全由工程造成。","用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Any vegetation increase after treatment proves that the project caused the entire increase.","Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling."],"answer":2,"explanation":"用沉陷板和孔壓觀測區分材料壓密與原地基移動，核對孔隙比樣本的代表性。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use settlement and pore-pressure observations to distinguish placed-layer consolidation from foundation movement, checking void-ratio sampling. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b288-v15-12","title":"壓密後高程餘量：失效診斷","titleEn":"Post-consolidation elevation reserve: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-11"],"objective":"從症狀倒推「壓密後高程餘量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Post-consolidation elevation reserve” and propose discriminating checks, corrective actions and prevention.","instruction":"把原地基沉陷也算成填料壓密會誤估所需材料，未考慮側向流動又可能低估低處擴散。高程達標後持續下降會改變植被帶與潮溝連通，影響復育功能。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Assigning foundation settlement entirely to fill consolidation misstates material demand, while omitted spreading understates movement into low areas. Continued lowering after nominal completion alters vegetation zones and creek connectivity, changing the intended restoration function. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設初厚1m、初孔隙比e0=2、末孔隙比e1=1，末厚H1=H0(1+e1)/(1+e0)=0.667m，沉陷0.333m。","observationEn":"Link to the mechanism: H1=H0(1+e1)/(1+e0)=0.667m and settlement0.333m, with fixed solid volume.","failure":"誤判風險：若相信「放置材料乾固體沒有流失就代表地表高程不會再下降。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"If placed dry solids are retained, surface elevation cannot subsequently decrease.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-12-k1","title":"失效模式","titleEn":"Failure mode","text":"把原地基沉陷也算成填料壓密會誤估所需材料，未考慮側向流動又可能低估低處擴散。高程達標後持續下降會改變植被帶與潮溝連通，影響復育功能。","textEn":"Assigning foundation settlement entirely to fill consolidation misstates material demand, while omitted spreading understates movement into low areas. Continued lowering after nominal completion alters vegetation zones and creek connectivity, changing the intended restoration function.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「壓密後高程餘量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Post-consolidation elevation reserve\" shows distress, which diagnosis is most reasonable?","options":["把原地基沉陷也算成填料壓密會誤估所需材料，未考慮側向流動又可能低估低處擴散。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","潮位超過地面的時間比例直接等於植被的存活機率。"],"optionsEn":["Assigning foundation settlement entirely to fill consolidation misstates material demand, while omitted spreading understates movement into low areas.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","The fraction of time tide exceeds ground directly equals plant survival probability."],"answer":0,"explanation":"把原地基沉陷也算成填料壓密會誤估所需材料，未考慮側向流動又可能低估低處擴散。 需以量測區分可能原因。","explanationEn":"Assigning foundation settlement entirely to fill consolidation misstates material demand, while omitted spreading understates movement into low areas. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b288-v15-13","title":"潮汐淹水比例：機制與系統路徑","titleEn":"Tidal inundation fraction: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-12"],"objective":"說明「潮汐淹水比例」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Tidal inundation fraction” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"潮位與地面高程的相對關係決定浸水時間，對植被及水質交換都重要。單一正弦潮忽略不對稱、風增水與排水滯後，但能說明高程小變動如何改變淹水比例；時間比例不同於水深，也不能直接換成某物種存活率或生態成功機率。 假設潮位η=A sinωt、A=1m、地面z=0.5m且無滯水，淹水比例arccos(z/A)/π=1/3，非存活率。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「潮汐淹水比例」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Relative tide and ground elevation determine inundation duration, affecting vegetation and exchange. One sinusoid omits asymmetry, wind setup and drainage lag but illustrates how elevation changes alter the wet fraction. Duration fraction differs from water depth and cannot directly become a species-survival probability or a general measure of ecological success at the restoration site. Assume tideη=A sinωt,A=1m and ground z=0.5m without ponding. Inundation fraction arccos(z/A)/π=1/3, not survival probability. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Tidal inundation fraction” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「潮位超過地面的時間比例直接等於植被的存活機率。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The fraction of time tide exceeds ground directly equals plant survival probability.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「潮汐淹水比例」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Tidal inundation fraction”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-13-k1","title":"潮汐淹水比例","titleEn":"Tidal inundation fraction","text":"潮位與地面高程的相對關係決定浸水時間，對植被及水質交換都重要。單一正弦潮忽略不對稱、風增水與排水滯後，但能說明高程小變動如何改變淹水比例；時間比例不同於水深，也不能直接換成某物種存活率或生態成功機率。","textEn":"Relative tide and ground elevation determine inundation duration, affecting vegetation and exchange. One sinusoid omits asymmetry, wind setup and drainage lag but illustrates how elevation changes alter the wet fraction.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：潮位超過地面的時間比例直接等於植被的存活機率。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The fraction of time tide exceeds ground directly equals plant survival probability. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「潮汐淹水比例」，下列哪一項敘述正確？","questionEn":"Which statement about \"Tidal inundation fraction\" is correct?","options":["潮位超過地面的時間比例直接等於植被的存活機率。","潮位與地面高程的相對關係決定浸水時間，對植被及水質交換都重要。","產品純度與原料回收率永遠具有相同分母而且相等。"],"optionsEn":["The fraction of time tide exceeds ground directly equals plant survival probability.","Relative tide and ground elevation determine inundation duration, affecting vegetation and exchange.","Product purity and feed recovery always share the same denominator and value."],"answer":1,"explanation":"潮位與地面高程的相對關係決定浸水時間，對植被及水質交換都重要。 其餘選項是常見誤解。","explanationEn":"Relative tide and ground elevation determine inundation duration, affecting vegetation and exchange. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b288-v15-14","title":"潮汐淹水比例：定量估算","titleEn":"Tidal inundation fraction: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-13"],"objective":"以數值模型估算「潮汐淹水比例」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tidal inundation fraction” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設潮位η=A sinωt、A=1m、地面z=0.5m且無滯水，淹水比例arccos(z/A)/π=1/3，非存活率。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume tideη=A sinωt,A=1m and ground z=0.5m without ponding. Inundation fraction arccos(z/A)/π=1/3, not survival probability. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。","observationEn":"How to cross-check: Record terrain and tide on one datum and count exceedance time while checking post-tide ponding.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設潮位η=A sinωt、A=1m、地面z=0.5m且無滯水，淹水比例arccos(z/A)/π=1/3，非存活率。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume tideη=A sinωt,A=1m and ground z=0.5m without ponding. Inundation fraction arccos(z/A)/π=1/3, not survival probability.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「潮汐淹水比例」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Tidal inundation fraction\", which statement holds?","options":["覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。","運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。","教學假設，非操作設定或設計允收值。"],"optionsEn":["Enough total cover volume proves adequate thickness and chemical isolation everywhere.","The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b288-v15-15","title":"潮汐淹水比例：試驗與驗證","titleEn":"Tidal inundation fraction: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「潮汐淹水比例」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tidal inundation fraction” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。按季節和植被區分組比較，說明正弦示意漏掉的長週期變化與降雨，不用單次高潮代表全年。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record terrain and tide on one datum and count exceedance time while checking post-tide ponding. Compare by season and vegetation zone, identifying long-period variation and rainfall omitted by the sinusoid rather than treating one high tide as representative of the year. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。按季節和植被區分組比較，說明正弦示意漏掉的長週期變化與降雨，不用單次高潮代表全年。","observationEn":"Site practice: Record terrain and tide on one datum and count exceedance time while checking post-tide ponding. Compare by season and vegetation zone, identifying long-period variation and rainfall omitted by the sinusoid rather than treating one high tide as representative of the year.","failure":"注意干擾：排水溝阻塞會使實際浸水長於海潮超越時間，基準偏差又會把植被帶放錯高程。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Blocked drainage prolongs inundation beyond tidal exceedance, while datum errors misplace vegetation zones. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-15-k1","title":"驗證方法","titleEn":"Verification method","text":"以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。按季節和植被區分組比較，說明正弦示意漏掉的長週期變化與降雨，不用單次高潮代表全年。","textEn":"Record terrain and tide on one datum and count exceedance time while checking post-tide ponding. Compare by season and vegetation zone, identifying long-period variation and rainfall omitted by the sinusoid rather than treating one high tide as representative of the year.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-15-k2","title":"現場實務","titleEn":"Site practice","text":"以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。按季節和植被區分組比較，說明正弦示意漏掉的長週期變化與降雨，不用單次高潮代表全年。","textEn":"Record terrain and tide on one datum and count exceedance time while checking post-tide ponding. Compare by season and vegetation zone, identifying long-period variation and rainfall omitted by the sinusoid rather than treating one high tide as representative of the year.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「潮汐淹水比例」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Tidal inundation fraction\"?","options":["以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。","不確定度太難估計，報告中只寫最佳值即可。","疏浚材料只要有預定去向就全部算成已驗證成功再利用。"],"optionsEn":["Record terrain and tide on one datum and count exceedance time while checking post-tide ponding.","Uncertainty is too hard to estimate, so the report may state only the best value.","Every dredged batch with a planned destination already counts as verified successful reuse."],"answer":0,"explanation":"以同一高程基準記錄地面與潮位序列，實算超過地面時間並檢查退潮後積水。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record terrain and tide on one datum and count exceedance time while checking post-tide ponding. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b288-v15-16","title":"潮汐淹水比例：失效診斷","titleEn":"Tidal inundation fraction: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-15"],"objective":"從症狀倒推「潮汐淹水比例」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tidal inundation fraction” and propose discriminating checks, corrective actions and prevention.","instruction":"排水溝阻塞會使實際浸水長於海潮超越時間，基準偏差又會把植被帶放錯高程。只用平均潮差而不看長時間序列，可能漏掉持續積水的關鍵事件。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Blocked drainage prolongs inundation beyond tidal exceedance, while datum errors misplace vegetation zones. A mean tidal range without a long record can miss the sustained flooding events that govern the actual response of restored habitat. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設潮位η=A sinωt、A=1m、地面z=0.5m且無滯水，淹水比例arccos(z/A)/π=1/3，非存活率。","observationEn":"Link to the mechanism: Inundation fraction arccos(z/A)/π=1/3, not survival probability.","failure":"誤判風險：若相信「潮位超過地面的時間比例直接等於植被的存活機率。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The fraction of time tide exceeds ground directly equals plant survival probability.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-16-k1","title":"失效模式","titleEn":"Failure mode","text":"排水溝阻塞會使實際浸水長於海潮超越時間，基準偏差又會把植被帶放錯高程。只用平均潮差而不看長時間序列，可能漏掉持續積水的關鍵事件。","textEn":"Blocked drainage prolongs inundation beyond tidal exceedance, while datum errors misplace vegetation zones. A mean tidal range without a long record can miss the sustained flooding events that govern the actual response of restored habitat.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「潮汐淹水比例」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Tidal inundation fraction\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","排水溝阻塞會使實際浸水長於海潮超越時間，基準偏差又會把植被帶放錯高程。","產品純度與原料回收率永遠具有相同分母而且相等。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Blocked drainage prolongs inundation beyond tidal exceedance, while datum errors misplace vegetation zones.","Product purity and feed recovery always share the same denominator and value."],"answer":1,"explanation":"排水溝阻塞會使實際浸水長於海潮超越時間，基準偏差又會把植被帶放錯高程。 需以量測區分可能原因。","explanationEn":"Blocked drainage prolongs inundation beyond tidal exceedance, while datum errors misplace vegetation zones. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b288-v15-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「篩分回收與產率」與「污染質量與濃度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Screening recovery and yield\" and \"Contaminant mass versus concentration\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b288-v15-17","title":"篩分回收與產率：機制與系統路徑","titleEn":"Screening recovery and yield: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-16"],"objective":"說明「篩分回收與產率」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Screening recovery and yield” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"分離處理需同時看產品中目標粒群的純度和原料目標粒群的回收率，兩者分母不同。增加篩分強度可能提高純度卻流失可用砂，且濕篩和乾篩結果需統一基準；工程用途還要求其他性質，因此產品比例不能被當成最終可用性證明。 假設原料乾砂600t，產品含砂540t且產品總乾質量600t；砂回收率540/600=90%，產品純度也90%，分母巧合相同。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「篩分回收與產率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Separation must distinguish product purity from recovery of the target fraction in the feed, because the denominators differ. More aggressive screening may increase purity while losing usable sand, and wet and dry results require one basis. Intended use imposes additional properties, so a high product fraction does not itself qualify the material for placement or structural performance. Assume feed contains600t dry sand; product contains540t sand in600t total dry mass. Recovery and purity are both90%, with coincidentally equal denominators. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Screening recovery and yield” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「產品純度與原料回收率永遠具有相同分母而且相等。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Product purity and feed recovery always share the same denominator and value.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「篩分回收與產率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Screening recovery and yield”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-17-k1","title":"篩分回收與產率","titleEn":"Screening recovery and yield","text":"分離處理需同時看產品中目標粒群的純度和原料目標粒群的回收率，兩者分母不同。增加篩分強度可能提高純度卻流失可用砂，且濕篩和乾篩結果需統一基準；工程用途還要求其他性質，因此產品比例不能被當成最終可用性證明。","textEn":"Separation must distinguish product purity from recovery of the target fraction in the feed, because the denominators differ. More aggressive screening may increase purity while losing usable sand, and wet and dry results require one basis.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：產品純度與原料回收率永遠具有相同分母而且相等。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Product purity and feed recovery always share the same denominator and value. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「篩分回收與產率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Screening recovery and yield\" is correct?","options":["產品純度與原料回收率永遠具有相同分母而且相等。","混合後平均濃度降低代表同百分比的污染物已被消除。","分離處理需同時看產品中目標粒群的純度和原料目標粒群的回收率，兩者分母不同。"],"optionsEn":["Product purity and feed recovery always share the same denominator and value.","A lower average concentration after mixing means the same fraction of contaminant was destroyed.","Separation must distinguish product purity from recovery of the target fraction in the feed, because the denominators differ."],"answer":2,"explanation":"分離處理需同時看產品中目標粒群的純度和原料目標粒群的回收率，兩者分母不同。 其餘選項是常見誤解。","explanationEn":"Separation must distinguish product purity from recovery of the target fraction in the feed, because the denominators differ. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b288-v15-18","title":"篩分回收與產率：定量估算","titleEn":"Screening recovery and yield: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-17"],"objective":"以數值模型估算「篩分回收與產率」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Screening recovery and yield” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設原料乾砂600t，產品含砂540t且產品總乾質量600t；砂回收率540/600=90%，產品純度也90%，分母巧合相同。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume feed contains600t dry sand; product contains540t sand in600t total dry mass. Recovery and purity are both90%, with coincidentally equal denominators. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。","observationEn":"How to cross-check: Sample feed, product and reject streams and close the target fraction’s dry-mass balance.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設原料乾砂600t，產品含砂540t且產品總乾質量600t；砂回收率540/600=90%，產品純度也90%，分母巧合相同。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume feed contains600t dry sand; product contains540t sand in600t total dry mass. Recovery and purity are both90%, with coincidentally equal denominators.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「篩分回收與產率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Screening recovery and yield\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","表面變乾就代表全部填料已完全排水並取得最終強度。","處理區施工後植被增加就足以證明增長完全由工程造成。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","A dry surface proves that the entire fill has drained and reached final strength.","Any vegetation increase after treatment proves that the project caused the entire increase."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b288-v15-19","title":"篩分回收與產率：試驗與驗證","titleEn":"Screening recovery and yield: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「篩分回收與產率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Screening recovery and yield” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。用兩個不同分母重新計算回收與純度，檢查細料附著和含水偏差，並記錄未被篩分指標代表的材料需求。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Sample feed, product and reject streams and close the target fraction’s dry-mass balance. Recalculate recovery and purity using their distinct denominators, checking attached fines and moisture bias, and list material requirements that screening metrics alone do not represent. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。用兩個不同分母重新計算回收與純度，檢查細料附著和含水偏差，並記錄未被篩分指標代表的材料需求。","observationEn":"Site practice: Sample feed, product and reject streams and close the target fraction’s dry-mass balance. Recalculate recovery and purity using their distinct denominators, checking attached fines and moisture bias, and list material requirements that screening metrics alone do not represent.","failure":"注意干擾：把產品純度當回收率可能隱藏大量好砂被丟棄，反之回收率高也可能得到含細料過多的產品。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Substituting purity for recovery can conceal discarded good sand, while high recovery may produce an excessively fine-rich product. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-19-k1","title":"驗證方法","titleEn":"Verification method","text":"分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。用兩個不同分母重新計算回收與純度，檢查細料附著和含水偏差，並記錄未被篩分指標代表的材料需求。","textEn":"Sample feed, product and reject streams and close the target fraction’s dry-mass balance. Recalculate recovery and purity using their distinct denominators, checking attached fines and moisture bias, and list material requirements that screening metrics alone do not represent.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-19-k2","title":"現場實務","titleEn":"Site practice","text":"分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。用兩個不同分母重新計算回收與純度，檢查細料附著和含水偏差，並記錄未被篩分指標代表的材料需求。","textEn":"Sample feed, product and reject streams and close the target fraction’s dry-mass balance. Recalculate recovery and purity using their distinct denominators, checking attached fines and moisture bias, and list material requirements that screening metrics alone do not represent.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「篩分回收與產率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Screening recovery and yield\"?","options":["允收準則可以等看到量測數據後再決定。","分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。","平均放置厚度達標就能證明每個位置的淹水條件都合適。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Sample feed, product and reject streams and close the target fraction’s dry-mass balance.","A satisfactory mean placement thickness proves suitable inundation at every location."],"answer":1,"explanation":"分別採原料、產品和排除物樣本，建立目標粒群的完整乾質量平衡。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Sample feed, product and reject streams and close the target fraction’s dry-mass balance. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b288-v15-20","title":"篩分回收與產率：失效診斷","titleEn":"Screening recovery and yield: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-19"],"objective":"從症狀倒推「篩分回收與產率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Screening recovery and yield” and propose discriminating checks, corrective actions and prevention.","instruction":"把產品純度當回收率可能隱藏大量好砂被丟棄，反之回收率高也可能得到含細料過多的產品。只有單一產品樣本，不能追查分離設備真正的物料去向。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Substituting purity for recovery can conceal discarded good sand, while high recovery may produce an excessively fine-rich product. A product-only sample cannot reveal the actual routing of material through the separation process. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設原料乾砂600t，產品含砂540t且產品總乾質量600t；砂回收率540/600=90%，產品純度也90%，分母巧合相同。","observationEn":"Link to the mechanism: Recovery and purity are both90%, with coincidentally equal denominators.","failure":"誤判風險：若相信「產品純度與原料回收率永遠具有相同分母而且相等。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Product purity and feed recovery always share the same denominator and value.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-20-k1","title":"失效模式","titleEn":"Failure mode","text":"把產品純度當回收率可能隱藏大量好砂被丟棄，反之回收率高也可能得到含細料過多的產品。只有單一產品樣本，不能追查分離設備真正的物料去向。","textEn":"Substituting purity for recovery can conceal discarded good sand, while high recovery may produce an excessively fine-rich product. A product-only sample cannot reveal the actual routing of material through the separation process.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「篩分回收與產率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Screening recovery and yield\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","混合後平均濃度降低代表同百分比的污染物已被消除。","把產品純度當回收率可能隱藏大量好砂被丟棄，反之回收率高也可能得到含細料過多的產品。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A lower average concentration after mixing means the same fraction of contaminant was destroyed.","Substituting purity for recovery can conceal discarded good sand, while high recovery may produce an excessively fine-rich product."],"answer":2,"explanation":"把產品純度當回收率可能隱藏大量好砂被丟棄，反之回收率高也可能得到含細料過多的產品。 需以量測區分可能原因。","explanationEn":"Substituting purity for recovery can conceal discarded good sand, while high recovery may produce an excessively fine-rich product. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b288-v15-21","title":"污染質量與濃度：機制與系統路徑","titleEn":"Contaminant mass versus concentration: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-20"],"objective":"說明「污染質量與濃度」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Contaminant mass versus concentration” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"固體污染物濃度乘乾質量可得到總負荷，這與孔隙水溶出或生物可利用性不同。混合會改變平均濃度卻不讓污染物消失，因此守恆算例絕不能被當成稀釋達標方法；評估須依物質、暴露路徑和適用法域選用檢測，不能只憑平均數決定用途。 假設乾料1000t、某示蹤物20mg/kg，總量20kg；加入1000t不含該物材料後均濃度10mg/kg，但總量仍20kg。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「污染質量與濃度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Dry-basis concentration times sediment mass gives total burden, distinct from dissolved release or bioavailability. Mixing changes mean concentration without destroying contaminants, so this conservation example must never be treated as a dilution-to-compliance method. Evaluation requires substance-specific tests, exposure pathways and applicable jurisdiction, not a use decision based solely on a convenient bulk average. Assume1000t dry sediment at tracer concentration20mg/kg: total20kg. Adding1000t tracer-free material gives10mg/kg while total remains20kg; no compliance claim. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Contaminant mass versus concentration” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「混合後平均濃度降低代表同百分比的污染物已被消除。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A lower average concentration after mixing means the same fraction of contaminant was destroyed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「污染質量與濃度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Contaminant mass versus concentration”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-21-k1","title":"污染質量與濃度","titleEn":"Contaminant mass versus concentration","text":"固體污染物濃度乘乾質量可得到總負荷，這與孔隙水溶出或生物可利用性不同。混合會改變平均濃度卻不讓污染物消失，因此守恆算例絕不能被當成稀釋達標方法；評估須依物質、暴露路徑和適用法域選用檢測，不能只憑平均數決定用途。","textEn":"Dry-basis concentration times sediment mass gives total burden, distinct from dissolved release or bioavailability. Mixing changes mean concentration without destroying contaminants, so this conservation example must never be treated as a dilution-to-compliance method.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：混合後平均濃度降低代表同百分比的污染物已被消除。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A lower average concentration after mixing means the same fraction of contaminant was destroyed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「污染質量與濃度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Contaminant mass versus concentration\" is correct?","options":["固體污染物濃度乘乾質量可得到總負荷，這與孔隙水溶出或生物可利用性不同。","混合後平均濃度降低代表同百分比的污染物已被消除。","覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。"],"optionsEn":["Dry-basis concentration times sediment mass gives total burden, distinct from dissolved release or bioavailability.","A lower average concentration after mixing means the same fraction of contaminant was destroyed.","Enough total cover volume proves adequate thickness and chemical isolation everywhere."],"answer":0,"explanation":"固體污染物濃度乘乾質量可得到總負荷，這與孔隙水溶出或生物可利用性不同。 其餘選項是常見誤解。","explanationEn":"Dry-basis concentration times sediment mass gives total burden, distinct from dissolved release or bioavailability. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b288-v15-22","title":"污染質量與濃度：定量估算","titleEn":"Contaminant mass versus concentration: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-21"],"objective":"以數值模型估算「污染質量與濃度」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Contaminant mass versus concentration” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設乾料1000t、某示蹤物20mg/kg，總量20kg；加入1000t不含該物材料後均濃度10mg/kg，但總量仍20kg。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume1000t dry sediment at tracer concentration20mg/kg: total20kg. Adding1000t tracer-free material gives10mg/kg while total remains20kg; no compliance claim. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。","observationEn":"How to cross-check: Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設乾料1000t、某示蹤物20mg/kg，總量20kg；加入1000t不含該物材料後均濃度10mg/kg，但總量仍20kg。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume1000t dry sediment at tracer concentration20mg/kg: total20kg. Adding1000t tracer-free material gives10mg/kg while total remains20kg; no compliance claim.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「污染質量與濃度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Contaminant mass versus concentration\", which statement holds?","options":["運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。","教學假設，非操作設定或設計允收值。","疏浚材料只要有預定去向就全部算成已驗證成功再利用。"],"optionsEn":["The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.","Teaching assumptions, not operating settings or design acceptance limits.","Every dredged batch with a planned destination already counts as verified successful reuse."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b288-v15-23","title":"污染質量與濃度：試驗與驗證","titleEn":"Contaminant mass versus concentration: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「污染質量與濃度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Contaminant mass versus concentration” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。另查溶出、生物暴露及材料用途的必要試驗，將任何混合方案交由適用程序評估，不把降低平均值當成去除污染。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration. Evaluate required leaching, biological exposure and intended-use tests through the applicable process, without treating a lower mixed average as removal of the substance. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。另查溶出、生物暴露及材料用途的必要試驗，將任何混合方案交由適用程序評估，不把降低平均值當成去除污染。","observationEn":"Site practice: Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration. Evaluate required leaching, biological exposure and intended-use tests through the applicable process, without treating a lower mixed average as removal of the substance.","failure":"注意干擾：熱點被大量低濃度樣本平均後可能消失在報表中，總負荷和局部接觸仍存在。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A hotspot can disappear statistically among low-concentration samples while burden and local exposure persist. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-23-k1","title":"驗證方法","titleEn":"Verification method","text":"保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。另查溶出、生物暴露及材料用途的必要試驗，將任何混合方案交由適用程序評估，不把降低平均值當成去除污染。","textEn":"Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration. Evaluate required leaching, biological exposure and intended-use tests through the applicable process, without treating a lower mixed average as removal of the substance.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-23-k2","title":"現場實務","titleEn":"Site practice","text":"保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。另查溶出、生物暴露及材料用途的必要試驗，將任何混合方案交由適用程序評估，不把降低平均值當成去除污染。","textEn":"Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration. Evaluate required leaching, biological exposure and intended-use tests through the applicable process, without treating a lower mixed average as removal of the substance.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「污染質量與濃度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Contaminant mass versus concentration\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","放置材料乾固體沒有流失就代表地表高程不會再下降。","保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","If placed dry solids are retained, surface elevation cannot subsequently decrease.","Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration."],"answer":2,"explanation":"保留乾基定義、採樣分區與分析品質資料，分別計算總質量與濃度。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Retain dry-basis definition, sampling zones and analytical quality records, calculating burden separately from concentration. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b288-v15-24","title":"污染質量與濃度：失效診斷","titleEn":"Contaminant mass versus concentration: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-23"],"objective":"從症狀倒推「污染質量與濃度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Contaminant mass versus concentration” and propose discriminating checks, corrective actions and prevention.","instruction":"熱點被大量低濃度樣本平均後可能消失在報表中，總負荷和局部接觸仍存在。以稀釋比例代替處理成效會漏掉溶出條件改變和生物累積的可能途徑。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A hotspot can disappear statistically among low-concentration samples while burden and local exposure persist. Replacing treatment evidence with a dilution ratio overlooks changes in leaching conditions and possible pathways for biological accumulation after placement. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設乾料1000t、某示蹤物20mg/kg，總量20kg；加入1000t不含該物材料後均濃度10mg/kg，但總量仍20kg。","observationEn":"Link to the mechanism: Adding1000t tracer-free material gives10mg/kg while total remains20kg; no compliance claim.","failure":"誤判風險：若相信「混合後平均濃度降低代表同百分比的污染物已被消除。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A lower average concentration after mixing means the same fraction of contaminant was destroyed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-24-k1","title":"失效模式","titleEn":"Failure mode","text":"熱點被大量低濃度樣本平均後可能消失在報表中，總負荷和局部接觸仍存在。以稀釋比例代替處理成效會漏掉溶出條件改變和生物累積的可能途徑。","textEn":"A hotspot can disappear statistically among low-concentration samples while burden and local exposure persist. Replacing treatment evidence with a dilution ratio overlooks changes in leaching conditions and possible pathways for biological accumulation after placement.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「污染質量與濃度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Contaminant mass versus concentration\" shows distress, which diagnosis is most reasonable?","options":["熱點被大量低濃度樣本平均後可能消失在報表中，總負荷和局部接觸仍存在。","只要結構還沒倒，就代表安全餘裕仍然足夠。","覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。"],"optionsEn":["A hotspot can disappear statistically among low-concentration samples while burden and local exposure persist.","As long as the structure is still standing, its safety margin must still be adequate.","Enough total cover volume proves adequate thickness and chemical isolation everywhere."],"answer":0,"explanation":"熱點被大量低濃度樣本平均後可能消失在報表中，總負荷和局部接觸仍存在。 需以量測區分可能原因。","explanationEn":"A hotspot can disappear statistically among low-concentration samples while burden and local exposure persist. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b288-v15-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「覆蓋厚度與侵蝕餘量」與「填料有效應力」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Cover thickness and erosion reserve\" and \"Effective stress in placed sediment\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b288-v15-25","title":"覆蓋厚度與侵蝕餘量：機制與系統路徑","titleEn":"Cover thickness and erosion reserve: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-24"],"objective":"說明「覆蓋厚度與侵蝕餘量」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Cover thickness and erosion reserve” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"隔離覆蓋層需維持連續厚度，平均放置量不能代表局部最薄處。侵蝕、壓密和底泥混入會消耗幾何餘量，而化學隔離還涉及擴散與生物擾動；本課只計厚度收支，不提供任何污染場址的建議覆蓋規格或長期隔離保證。 假設初始覆蓋0.50m、侵蝕0.08m、壓密0.04m且均勻，剩餘0.38m；未考慮混層、擴散與生物擾動。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「覆蓋厚度與侵蝕餘量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A cover layer needs continuous thickness, and average placed quantity does not describe its thinnest location. Erosion, consolidation and mixing consume geometric reserve, while chemical isolation also involves diffusion and biological disturbance. This lesson only accounts for thickness; it supplies no recommended contaminated-site cap specification and cannot establish durable isolation from the remaining number alone. Assume initial cover0.50m,erosion0.08m and compression0.04m uniformly. Remaining thickness is0.38m, excluding mixing, diffusion and bioturbation. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Cover thickness and erosion reserve” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Enough total cover volume proves adequate thickness and chemical isolation everywhere.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「覆蓋厚度與侵蝕餘量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Cover thickness and erosion reserve”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-25-k1","title":"覆蓋厚度與侵蝕餘量","titleEn":"Cover thickness and erosion reserve","text":"隔離覆蓋層需維持連續厚度，平均放置量不能代表局部最薄處。侵蝕、壓密和底泥混入會消耗幾何餘量，而化學隔離還涉及擴散與生物擾動；本課只計厚度收支，不提供任何污染場址的建議覆蓋規格或長期隔離保證。","textEn":"A cover layer needs continuous thickness, and average placed quantity does not describe its thinnest location. Erosion, consolidation and mixing consume geometric reserve, while chemical isolation also involves diffusion and biological disturbance.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Enough total cover volume proves adequate thickness and chemical isolation everywhere. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「覆蓋厚度與侵蝕餘量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cover thickness and erosion reserve\" is correct?","options":["覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。","隔離覆蓋層需維持連續厚度，平均放置量不能代表局部最薄處。","表面變乾就代表全部填料已完全排水並取得最終強度。"],"optionsEn":["Enough total cover volume proves adequate thickness and chemical isolation everywhere.","A cover layer needs continuous thickness, and average placed quantity does not describe its thinnest location.","A dry surface proves that the entire fill has drained and reached final strength."],"answer":1,"explanation":"隔離覆蓋層需維持連續厚度，平均放置量不能代表局部最薄處。 其餘選項是常見誤解。","explanationEn":"A cover layer needs continuous thickness, and average placed quantity does not describe its thinnest location. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b288-v15-26","title":"覆蓋厚度與侵蝕餘量：定量估算","titleEn":"Cover thickness and erosion reserve: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-25"],"objective":"以數值模型估算「覆蓋厚度與侵蝕餘量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cover thickness and erosion reserve” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設初始覆蓋0.50m、侵蝕0.08m、壓密0.04m且均勻，剩餘0.38m；未考慮混層、擴散與生物擾動。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume initial cover0.50m,erosion0.08m and compression0.04m uniformly. Remaining thickness is0.38m, excluding mixing, diffusion and bioturbation. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。","observationEn":"How to cross-check: Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設初始覆蓋0.50m、侵蝕0.08m、壓密0.04m且均勻，剩餘0.38m；未考慮混層、擴散與生物擾動。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume initial cover0.50m,erosion0.08m and compression0.04m uniformly. Remaining thickness is0.38m, excluding mixing, diffusion and bioturbation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「覆蓋厚度與侵蝕餘量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cover thickness and erosion reserve\", which statement holds?","options":["處理區施工後植被增加就足以證明增長完全由工程造成。","平均放置厚度達標就能證明每個位置的淹水條件都合適。","教學假設，非操作設定或設計允收值。"],"optionsEn":["Any vegetation increase after treatment proves that the project caused the entire increase.","A satisfactory mean placement thickness proves suitable inundation at every location.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b288-v15-27","title":"覆蓋厚度與侵蝕餘量：試驗與驗證","titleEn":"Cover thickness and erosion reserve: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「覆蓋厚度與侵蝕餘量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cover thickness and erosion reserve” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。另查材料相容、滲流和生物作用，不讓幾何驗證取代完整隔離績效評估。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression. Assess compatibility, seepage and biological processes separately so geometric verification does not replace a complete isolation-performance evaluation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。另查材料相容、滲流和生物作用，不讓幾何驗證取代完整隔離績效評估。","observationEn":"Site practice: Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression. Assess compatibility, seepage and biological processes separately so geometric verification does not replace a complete isolation-performance evaluation.","failure":"注意干擾：覆蓋料與原泥混合會使外觀厚度足夠但隔離距離不足，局部沖槽也可能穿透平均合格的區域。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Mixing with native sediment can leave adequate apparent thickness but inadequate separation, while a local scour channel breaches an otherwise satisfactory average cover. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-27-k1","title":"驗證方法","titleEn":"Verification method","text":"用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。另查材料相容、滲流和生物作用，不讓幾何驗證取代完整隔離績效評估。","textEn":"Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression. Assess compatibility, seepage and biological processes separately so geometric verification does not replace a complete isolation-performance evaluation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-27-k2","title":"現場實務","titleEn":"Site practice","text":"用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。另查材料相容、滲流和生物作用，不讓幾何驗證取代完整隔離績效評估。","textEn":"Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression. Assess compatibility, seepage and biological processes separately so geometric verification does not replace a complete isolation-performance evaluation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「覆蓋厚度與侵蝕餘量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cover thickness and erosion reserve\"?","options":["用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","潮位超過地面的時間比例直接等於植被的存活機率。"],"optionsEn":["Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","The fraction of time tide exceeds ground directly equals plant survival probability."],"answer":0,"explanation":"用可辨識界面量測覆蓋層頂底，分區記錄最薄值和不確定度，核對侵蝕與壓密是否重複扣除。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure identifiable upper and lower interfaces, recording minimum thickness and uncertainty by zone and checking double-counted erosion or compression. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b288-v15-28","title":"覆蓋厚度與侵蝕餘量：失效診斷","titleEn":"Cover thickness and erosion reserve: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-27"],"objective":"從症狀倒推「覆蓋厚度與侵蝕餘量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cover thickness and erosion reserve” and propose discriminating checks, corrective actions and prevention.","instruction":"覆蓋料與原泥混合會使外觀厚度足夠但隔離距離不足，局部沖槽也可能穿透平均合格的區域。只依材料總方量驗收，無法找到控制暴露的薄弱路徑。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Mixing with native sediment can leave adequate apparent thickness but inadequate separation, while a local scour channel breaches an otherwise satisfactory average cover. Total material quantity cannot identify the thin pathways controlling actual exposure. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設初始覆蓋0.50m、侵蝕0.08m、壓密0.04m且均勻，剩餘0.38m；未考慮混層、擴散與生物擾動。","observationEn":"Link to the mechanism: Remaining thickness is0.38m, excluding mixing, diffusion and bioturbation.","failure":"誤判風險：若相信「覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Enough total cover volume proves adequate thickness and chemical isolation everywhere.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-28-k1","title":"失效模式","titleEn":"Failure mode","text":"覆蓋料與原泥混合會使外觀厚度足夠但隔離距離不足，局部沖槽也可能穿透平均合格的區域。只依材料總方量驗收，無法找到控制暴露的薄弱路徑。","textEn":"Mixing with native sediment can leave adequate apparent thickness but inadequate separation, while a local scour channel breaches an otherwise satisfactory average cover. Total material quantity cannot identify the thin pathways controlling actual exposure.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「覆蓋厚度與侵蝕餘量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cover thickness and erosion reserve\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","覆蓋料與原泥混合會使外觀厚度足夠但隔離距離不足，局部沖槽也可能穿透平均合格的區域。","表面變乾就代表全部填料已完全排水並取得最終強度。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Mixing with native sediment can leave adequate apparent thickness but inadequate separation, while a local scour channel breaches an otherwise satisfactory average cover.","A dry surface proves that the entire fill has drained and reached final strength."],"answer":1,"explanation":"覆蓋料與原泥混合會使外觀厚度足夠但隔離距離不足，局部沖槽也可能穿透平均合格的區域。 需以量測區分可能原因。","explanationEn":"Mixing with native sediment can leave adequate apparent thickness but inadequate separation, while a local scour channel breaches an otherwise satisfactory average cover. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b288-v15-29","title":"填料有效應力：機制與系統路徑","titleEn":"Effective stress in placed sediment: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-28"],"objective":"說明「填料有效應力」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Effective stress in placed sediment” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"新放置細泥的自重部分由孔隙水承受，有效應力才與土骨架壓縮及強度形成相關。總應力增加不等於立即取得同樣骨架荷載，排水時間和地層連通性需要量測；一個有效應力數值也不能直接代替剪力強度或允許設備通行荷重。 假設某點總垂直應力50kPa、孔隙壓35kPa，有效應力σ′=σ−u=15kPa；若總應力不變而u降10kPa，σ′升至25kPa。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「填料有效應力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Pore water supports part of freshly placed sediment weight; effective stress governs skeleton loading, compression and strength development. Increased total stress does not immediately become equal skeleton load, and drainage timing and connectivity need observation. One effective-stress result cannot replace a shear-strength evaluation or establish allowable equipment loading on a soft placement surface in the field. Assume total vertical stress50kPa and pore pressure35kPa:σ′=15kPa. At fixed total stress, a10kPa pressure fall raisesσ′ to25kPa. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Effective stress in placed sediment” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「表面變乾就代表全部填料已完全排水並取得最終強度。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A dry surface proves that the entire fill has drained and reached final strength.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「填料有效應力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Effective stress in placed sediment”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-29-k1","title":"填料有效應力","titleEn":"Effective stress in placed sediment","text":"新放置細泥的自重部分由孔隙水承受，有效應力才與土骨架壓縮及強度形成相關。總應力增加不等於立即取得同樣骨架荷載，排水時間和地層連通性需要量測；一個有效應力數值也不能直接代替剪力強度或允許設備通行荷重。","textEn":"Pore water supports part of freshly placed sediment weight; effective stress governs skeleton loading, compression and strength development. Increased total stress does not immediately become equal skeleton load, and drainage timing and connectivity need observation.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：表面變乾就代表全部填料已完全排水並取得最終強度。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A dry surface proves that the entire fill has drained and reached final strength. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「填料有效應力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Effective stress in placed sediment\" is correct?","options":["表面變乾就代表全部填料已完全排水並取得最終強度。","運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。","新放置細泥的自重部分由孔隙水承受，有效應力才與土骨架壓縮及強度形成相關。"],"optionsEn":["A dry surface proves that the entire fill has drained and reached final strength.","The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.","Pore water supports part of freshly placed sediment weight; effective stress governs skeleton loading, compression and strength development."],"answer":2,"explanation":"新放置細泥的自重部分由孔隙水承受，有效應力才與土骨架壓縮及強度形成相關。 其餘選項是常見誤解。","explanationEn":"Pore water supports part of freshly placed sediment weight; effective stress governs skeleton loading, compression and strength development. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b288-v15-30","title":"填料有效應力：定量估算","titleEn":"Effective stress in placed sediment: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-29"],"objective":"以數值模型估算「填料有效應力」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Effective stress in placed sediment” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設某點總垂直應力50kPa、孔隙壓35kPa，有效應力σ′=σ−u=15kPa；若總應力不變而u降10kPa，σ′升至25kPa。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume total vertical stress50kPa and pore pressure35kPa:σ′=15kPa. At fixed total stress, a10kPa pressure fall raisesσ′ to25kPa. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。","observationEn":"How to cross-check: Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設某點總垂直應力50kPa、孔隙壓35kPa，有效應力σ′=σ−u=15kPa；若總應力不變而u降10kPa，σ′升至25kPa。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume total vertical stress50kPa and pore pressure35kPa:σ′=15kPa. At fixed total stress, a10kPa pressure fall raisesσ′ to25kPa.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「填料有效應力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Effective stress in placed sediment\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","疏浚材料只要有預定去向就全部算成已驗證成功再利用。","放置材料乾固體沒有流失就代表地表高程不會再下降。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","Every dredged batch with a planned destination already counts as verified successful reuse.","If placed dry solids are retained, surface elevation cannot subsequently decrease."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b288-v15-31","title":"填料有效應力：試驗與驗證","titleEn":"Effective stress in placed sediment: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「填料有效應力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Effective stress in placed sediment” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。以獨立土樣或現地試驗追蹤強度演進，明列有效應力與承載判斷之間仍缺的材料關係。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together. Track strength with independent samples or field tests and state the constitutive relationships still needed between effective stress and a bearing assessment. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。以獨立土樣或現地試驗追蹤強度演進，明列有效應力與承載判斷之間仍缺的材料關係。","observationEn":"Site practice: Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together. Track strength with independent samples or field tests and state the constitutive relationships still needed between effective stress and a bearing assessment.","failure":"注意干擾：孔壓計零點漂移可能假造排水進展，忽略新增填土則錯判有效應力變化。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Piezometer drift can mimic drainage, while omitted new fill misstates effective-stress change. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-31-k1","title":"驗證方法","titleEn":"Verification method","text":"在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。以獨立土樣或現地試驗追蹤強度演進，明列有效應力與承載判斷之間仍缺的材料關係。","textEn":"Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together. Track strength with independent samples or field tests and state the constitutive relationships still needed between effective stress and a bearing assessment.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-31-k2","title":"現場實務","titleEn":"Site practice","text":"在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。以獨立土樣或現地試驗追蹤強度演進，明列有效應力與承載判斷之間仍缺的材料關係。","textEn":"Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together. Track strength with independent samples or field tests and state the constitutive relationships still needed between effective stress and a bearing assessment.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「填料有效應力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Effective stress in placed sediment\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。","產品純度與原料回收率永遠具有相同分母而且相等。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together.","Product purity and feed recovery always share the same denominator and value."],"answer":1,"explanation":"在同一高程與時刻比較孔壓和總荷載，檢查加載、潮位與排水的共同影響。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare pore pressure and total loading at matching elevations and times, checking loading, tide and drainage together. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b288-v15-32","title":"填料有效應力：失效診斷","titleEn":"Effective stress in placed sediment: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-31"],"objective":"從症狀倒推「填料有效應力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Effective stress in placed sediment” and propose discriminating checks, corrective actions and prevention.","instruction":"孔壓計零點漂移可能假造排水進展，忽略新增填土則錯判有效應力變化。表面看似乾燥而深部仍高孔壓時，設備荷載可能造成局部變形或側向擠出。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Piezometer drift can mimic drainage, while omitted new fill misstates effective-stress change. A dry-looking surface over persistently high deep pore pressures can still deform locally or squeeze laterally under equipment loading. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設某點總垂直應力50kPa、孔隙壓35kPa，有效應力σ′=σ−u=15kPa；若總應力不變而u降10kPa，σ′升至25kPa。","observationEn":"Link to the mechanism: At fixed total stress, a10kPa pressure fall raisesσ′ to25kPa.","failure":"誤判風險：若相信「表面變乾就代表全部填料已完全排水並取得最終強度。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A dry surface proves that the entire fill has drained and reached final strength.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-32-k1","title":"失效模式","titleEn":"Failure mode","text":"孔壓計零點漂移可能假造排水進展，忽略新增填土則錯判有效應力變化。表面看似乾燥而深部仍高孔壓時，設備荷載可能造成局部變形或側向擠出。","textEn":"Piezometer drift can mimic drainage, while omitted new fill misstates effective-stress change. A dry-looking surface over persistently high deep pore pressures can still deform locally or squeeze laterally under equipment loading.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「填料有效應力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Effective stress in placed sediment\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。","孔壓計零點漂移可能假造排水進展，忽略新增填土則錯判有效應力變化。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.","Piezometer drift can mimic drainage, while omitted new fill misstates effective-stress change."],"answer":2,"explanation":"孔壓計零點漂移可能假造排水進展，忽略新增填土則錯判有效應力變化。 需以量測區分可能原因。","explanationEn":"Piezometer drift can mimic drainage, while omitted new fill misstates effective-stress change. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b288-v15-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「運輸碳量比較」與「對照監測與歸因」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Transport emissions comparison\" and \"Control monitoring and attribution\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b288-v15-33","title":"運輸碳量比較：機制與系統路徑","titleEn":"Transport emissions comparison: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-32"],"objective":"說明「運輸碳量比較」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Transport emissions comparison” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"有益利用可改變材料運距與新料需求，但環境比較必須採相同功能和系統邊界。運輸噸公里只是部分排放，處理、泵送、空車回程及未避免的新料也可能重要；合成係數只練習計量，不能把局部節省包裝成完整生命週期淨收益。 假設10000t材料運距由50降至20km、係數0.08kgCO₂e/(t·km)，運輸差額10000×30×0.08=24000kgCO₂e。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「運輸碳量比較」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Reuse changes transport distance and demand for virgin material, but environmental comparisons require equivalent function and system boundaries. Tonne-kilometres describe only part of emissions; treatment, pumping, empty return trips and any unavoided supply also matter. A synthetic factor illustrates accounting rather than establishing complete life-cycle savings from a limited change in transport distance alone. Assume10000t moves20km instead of50km at0.08kgCO₂e/(t·km). Transport difference is24000kgCO₂e, excluding treatment and return-trip changes. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Transport emissions comparison” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「運輸碳量比較」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Transport emissions comparison”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-33-k1","title":"運輸碳量比較","titleEn":"Transport emissions comparison","text":"有益利用可改變材料運距與新料需求，但環境比較必須採相同功能和系統邊界。運輸噸公里只是部分排放，處理、泵送、空車回程及未避免的新料也可能重要；合成係數只練習計量，不能把局部節省包裝成完整生命週期淨收益。","textEn":"Reuse changes transport distance and demand for virgin material, but environmental comparisons require equivalent function and system boundaries. Tonne-kilometres describe only part of emissions; treatment, pumping, empty return trips and any unavoided supply also matter.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「運輸碳量比較」，下列哪一項敘述正確？","questionEn":"Which statement about \"Transport emissions comparison\" is correct?","options":["有益利用可改變材料運距與新料需求，但環境比較必須採相同功能和系統邊界。","運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。","處理區施工後植被增加就足以證明增長完全由工程造成。"],"optionsEn":["Reuse changes transport distance and demand for virgin material, but environmental comparisons require equivalent function and system boundaries.","The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.","Any vegetation increase after treatment proves that the project caused the entire increase."],"answer":0,"explanation":"有益利用可改變材料運距與新料需求，但環境比較必須採相同功能和系統邊界。 其餘選項是常見誤解。","explanationEn":"Reuse changes transport distance and demand for virgin material, but environmental comparisons require equivalent function and system boundaries. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b288-v15-34","title":"運輸碳量比較：定量估算","titleEn":"Transport emissions comparison: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-33"],"objective":"以數值模型估算「運輸碳量比較」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Transport emissions comparison” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設10000t材料運距由50降至20km、係數0.08kgCO₂e/(t·km)，運輸差額10000×30×0.08=24000kgCO₂e。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume10000t moves20km instead of50km at0.08kgCO₂e/(t·km). Transport difference is24000kgCO₂e, excluding treatment and return-trip changes. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。","observationEn":"How to cross-check: State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設10000t材料運距由50降至20km、係數0.08kgCO₂e/(t·km)，運輸差額10000×30×0.08=24000kgCO₂e。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume10000t moves20km instead of50km at0.08kgCO₂e/(t·km). Transport difference is24000kgCO₂e, excluding treatment and return-trip changes.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「運輸碳量比較」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Transport emissions comparison\", which statement holds?","options":["平均放置厚度達標就能證明每個位置的淹水條件都合適。","教學假設，非操作設定或設計允收值。","潮位超過地面的時間比例直接等於植被的存活機率。"],"optionsEn":["A satisfactory mean placement thickness proves suitable inundation at every location.","Teaching assumptions, not operating settings or design acceptance limits.","The fraction of time tide exceeds ground directly equals plant survival probability."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b288-v15-35","title":"運輸碳量比較：試驗與驗證","titleEn":"Transport emissions comparison: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「運輸碳量比較」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Transport emissions comparison” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。將處理、能耗和回程另列，對主要係數作敏感度比較，保留沒有證據可抵扣的項目。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance. List treatment, energy and return trips separately, test important factors for sensitivity, and retain items without evidence for any claimed avoided burden. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。將處理、能耗和回程另列，對主要係數作敏感度比較，保留沒有證據可抵扣的項目。","observationEn":"Site practice: State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance. List treatment, energy and return trips separately, test important factors for sensitivity, and retain items without evidence for any claimed avoided burden.","failure":"注意干擾：若再利用料需要額外長時間脫水，運輸減碳可能被處理能耗抵銷。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Extended dewatering may offset transport savings through treatment energy. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-35-k1","title":"驗證方法","titleEn":"Verification method","text":"明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。將處理、能耗和回程另列，對主要係數作敏感度比較，保留沒有證據可抵扣的項目。","textEn":"State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance. List treatment, energy and return trips separately, test important factors for sensitivity, and retain items without evidence for any claimed avoided burden.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-35-k2","title":"現場實務","titleEn":"Site practice","text":"明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。將處理、能耗和回程另列，對主要係數作敏感度比較，保留沒有證據可抵扣的項目。","textEn":"State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance. List treatment, energy and return trips separately, test important factors for sensitivity, and retain items without evidence for any claimed avoided burden.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「運輸碳量比較」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Transport emissions comparison\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","混合後平均濃度降低代表同百分比的污染物已被消除。","明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A lower average concentration after mixing means the same fraction of contaminant was destroyed.","State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance."],"answer":2,"explanation":"明列兩方案是否提供同樣材料功能與時間需求，記錄噸位、路程和排放係數來源。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"State whether alternatives deliver equivalent function and timing and document mass, distance and emission-factor provenance. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b288-v15-36","title":"運輸碳量比較：失效診斷","titleEn":"Transport emissions comparison: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-35"],"objective":"從症狀倒推「運輸碳量比較」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Transport emissions comparison” and propose discriminating checks, corrective actions and prevention.","instruction":"若再利用料需要額外長時間脫水，運輸減碳可能被處理能耗抵銷。把並未真正減少的新料生產扣除，或忽略空船回程，都會放大報表上的環境好處。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Extended dewatering may offset transport savings through treatment energy. Crediting virgin production that was not actually avoided, or ignoring an empty return voyage, further inflates the environmental benefit claimed for the reuse alternative. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設10000t材料運距由50降至20km、係數0.08kgCO₂e/(t·km)，運輸差額10000×30×0.08=24000kgCO₂e。","observationEn":"Link to the mechanism: Transport difference is24000kgCO₂e, excluding treatment and return-trip changes.","failure":"誤判風險：若相信「運距縮短的排放差額就是再利用方案完整的生命週期淨減碳。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The emissions saved by shorter transport equal the reuse project's complete life-cycle benefit.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-36-k1","title":"失效模式","titleEn":"Failure mode","text":"若再利用料需要額外長時間脫水，運輸減碳可能被處理能耗抵銷。把並未真正減少的新料生產扣除，或忽略空船回程，都會放大報表上的環境好處。","textEn":"Extended dewatering may offset transport savings through treatment energy. Crediting virgin production that was not actually avoided, or ignoring an empty return voyage, further inflates the environmental benefit claimed for the reuse alternative.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「運輸碳量比較」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Transport emissions comparison\" shows distress, which diagnosis is most reasonable?","options":["若再利用料需要額外長時間脫水，運輸減碳可能被處理能耗抵銷。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","處理區施工後植被增加就足以證明增長完全由工程造成。"],"optionsEn":["Extended dewatering may offset transport savings through treatment energy.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Any vegetation increase after treatment proves that the project caused the entire increase."],"answer":0,"explanation":"若再利用料需要額外長時間脫水，運輸減碳可能被處理能耗抵銷。 需以量測區分可能原因。","explanationEn":"Extended dewatering may offset transport savings through treatment energy. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b288-v15-37","title":"對照監測與歸因：機制與系統路徑","titleEn":"Control monitoring and attribution: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-36"],"objective":"說明「對照監測與歸因」如何影響疏浚泥沙有益利用的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Control monitoring and attribution” governs forces, deformation, flow or signals in “Beneficial reuse of dredged sediment”, and map the relevant inputs, transfer paths and boundaries.","instruction":"放置後植被或生物數量改變可能同時受季節、氣候與其他工程影響，單一前後差不能直接歸因。處理區與參照區的變化差提供較好的辨識起點，但仍依賴可比性和共同趨勢；多期及重複樣區可檢查這些假設，而不是以漂亮百分比宣布復育成功。 假設處理區植被覆蓋30%升50%、參照區40%升50%，差中差=(50−30)−(50−40)=10百分點；不是因果已證實。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「對照監測與歸因」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Post-placement ecological change can reflect season, climate or other works, so a simple before-after difference does not establish causation. Comparing changes in treatment and reference areas provides a stronger starting point but still requires comparability and parallel trends. Repeated periods and plots test those assumptions rather than allowing an attractive percentage to establish restoration success by itself. Assume treatment cover rises30%to50% and reference40%to50%. Difference-in-differences is10percentage points, not established causation without supporting assumptions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Control monitoring and attribution” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「處理區施工後植被增加就足以證明增長完全由工程造成。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Any vegetation increase after treatment proves that the project caused the entire increase.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「對照監測與歸因」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Control monitoring and attribution”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b288-v15-37-k1","title":"對照監測與歸因","titleEn":"Control monitoring and attribution","text":"放置後植被或生物數量改變可能同時受季節、氣候與其他工程影響，單一前後差不能直接歸因。處理區與參照區的變化差提供較好的辨識起點，但仍依賴可比性和共同趨勢；多期及重複樣區可檢查這些假設，而不是以漂亮百分比宣布復育成功。","textEn":"Post-placement ecological change can reflect season, climate or other works, so a simple before-after difference does not establish causation. Comparing changes in treatment and reference areas provides a stronger starting point but still requires comparability and parallel trends.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：處理區施工後植被增加就足以證明增長完全由工程造成。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Any vegetation increase after treatment proves that the project caused the entire increase. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"關於「對照監測與歸因」，下列哪一項敘述正確？","questionEn":"Which statement about \"Control monitoring and attribution\" is correct?","options":["處理區施工後植被增加就足以證明增長完全由工程造成。","放置後植被或生物數量改變可能同時受季節、氣候與其他工程影響，單一前後差不能直接歸因。","疏浚材料只要有預定去向就全部算成已驗證成功再利用。"],"optionsEn":["Any vegetation increase after treatment proves that the project caused the entire increase.","Post-placement ecological change can reflect season, climate or other works, so a simple before-after difference does not establish causation.","Every dredged batch with a planned destination already counts as verified successful reuse."],"answer":1,"explanation":"放置後植被或生物數量改變可能同時受季節、氣候與其他工程影響，單一前後差不能直接歸因。 其餘選項是常見誤解。","explanationEn":"Post-placement ecological change can reflect season, climate or other works, so a simple before-after difference does not establish causation. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b288-v15-38","title":"對照監測與歸因：定量估算","titleEn":"Control monitoring and attribution: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-37"],"objective":"以數值模型估算「對照監測與歸因」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Control monitoring and attribution” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設處理區植被覆蓋30%升50%、參照區40%升50%，差中差=(50−30)−(50−40)=10百分點；不是因果已證實。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume treatment cover rises30%to50% and reference40%to50%. Difference-in-differences is10percentage points, not established causation without supporting assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。","observationEn":"How to cross-check: Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b288-v15-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設處理區植被覆蓋30%升50%、參照區40%升50%，差中差=(50−30)−(50−40)=10百分點；不是因果已證實。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume treatment cover rises30%to50% and reference40%to50%. Difference-in-differences is10percentage points, not established causation without supporting assumptions.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"依「對照監測與歸因」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Control monitoring and attribution\", which statement holds?","options":["放置材料乾固體沒有流失就代表地表高程不會再下降。","產品純度與原料回收率永遠具有相同分母而且相等。","教學假設，非操作設定或設計允收值。"],"optionsEn":["If placed dry solids are retained, surface elevation cannot subsequently decrease.","Product purity and feed recovery always share the same denominator and value.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b288-v15-39","title":"對照監測與歸因：試驗與驗證","titleEn":"Control monitoring and attribution: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「對照監測與歸因」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Control monitoring and attribution” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。分開報告百分點、相對增幅及不確定度，追蹤物種組成與高程，避免只選有利單一指標。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas. Report percentage points, relative changes and uncertainty separately, tracking composition and elevation rather than selecting only a favorable single indicator. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。分開報告百分點、相對增幅及不確定度，追蹤物種組成與高程，避免只選有利單一指標。","observationEn":"Site practice: Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas. Report percentage points, relative changes and uncertainty separately, tracking composition and elevation rather than selecting only a favorable single indicator.","failure":"注意干擾：參照區若同時受到放置濁羽影響便不是獨立比較，前後季節不同也會造成假改善。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A reference affected by the placement plume is not an independent comparison, and different survey seasons create apparent improvement. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b288-v15-39-k1","title":"驗證方法","titleEn":"Verification method","text":"保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。分開報告百分點、相對增幅及不確定度，追蹤物種組成與高程，避免只選有利單一指標。","textEn":"Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas. Report percentage points, relative changes and uncertainty separately, tracking composition and elevation rather than selecting only a favorable single indicator.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-39-k2","title":"現場實務","titleEn":"Site practice","text":"保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。分開報告百分點、相對增幅及不確定度，追蹤物種組成與高程，避免只選有利單一指標。","textEn":"Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas. Report percentage points, relative changes and uncertainty separately, tracking composition and elevation rather than selecting only a favorable single indicator.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"要驗證「對照監測與歸因」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Control monitoring and attribution\"?","options":["保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。","不確定度太難估計，報告中只寫最佳值即可。","覆蓋材料總方量足夠就能證明各處隔離厚度與化學功能足夠。"],"optionsEn":["Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas.","Uncertainty is too hard to estimate, so the report may state only the best value.","Enough total cover volume proves adequate thickness and chemical isolation everywhere."],"answer":0,"explanation":"保留相同季節與方法的重複樣區，檢查施工前處理與參照區是否有近似趨勢。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Maintain repeated plots surveyed with the same seasonal method and examine pre-treatment trends in both areas. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b288-v15-40","title":"對照監測與歸因：失效診斷","titleEn":"Control monitoring and attribution: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"prerequisiteIds":["b288-v15-39"],"objective":"從症狀倒推「對照監測與歸因」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Control monitoring and attribution” and propose discriminating checks, corrective actions and prevention.","instruction":"參照區若同時受到放置濁羽影響便不是獨立比較，前後季節不同也會造成假改善。總覆蓋增加可能來自非目標物種，不能自動解釋為恢復預期棲地。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A reference affected by the placement plume is not an independent comparison, and different survey seasons create apparent improvement. Greater total cover may arise from nontarget species rather than recovery of the intended habitat function. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設處理區植被覆蓋30%升50%、參照區40%升50%，差中差=(50−30)−(50−40)=10百分點；不是因果已證實。","observationEn":"Link to the mechanism: Difference-in-differences is10percentage points, not established causation without supporting assumptions.","failure":"誤判風險：若相信「處理區施工後植被增加就足以證明增長完全由工程造成。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Any vegetation increase after treatment proves that the project caused the entire increase.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b288-v15-40-k1","title":"失效模式","titleEn":"Failure mode","text":"參照區若同時受到放置濁羽影響便不是獨立比較，前後季節不同也會造成假改善。總覆蓋增加可能來自非目標物種，不能自動解釋為恢復預期棲地。","textEn":"A reference affected by the placement plume is not an independent comparison, and different survey seasons create apparent improvement. Greater total cover may arise from nontarget species rather than recovery of the intended habitat function.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]},{"id":"b288-v15-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"]}],"quiz":{"question":"在「對照監測與歸因」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Control monitoring and attribution\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","參照區若同時受到放置濁羽影響便不是獨立比較，前後季節不同也會造成假改善。","疏浚材料只要有預定去向就全部算成已驗證成功再利用。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A reference affected by the placement plume is not an independent comparison, and different survey seasons create apparent improvement.","Every dredged batch with a planned destination already counts as verified successful reuse."],"answer":1,"explanation":"參照區若同時受到放置濁羽影響便不是獨立比較，前後季節不同也會造成假改善。 需以量測區分可能原因。","explanationEn":"A reference affected by the placement plume is not an independent comparison, and different survey seasons create apparent improvement. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v15s-itm","v15s-dredge","v15s-poplar","v15s-mordecai"],"curriculumVersion":15,"stepCount":40,"estimatedMinutes":1000}};
